/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const path = require('path');
const ts = require('/opt/typescript/lib/typescript.js');
const context = JSON.parse(fs.readFileSync('/work/context.json','utf8'));
const root = context.workspace;
const cfg = ts.parseConfigFileTextToJson('tsconfig.json',fs.readFileSync(path.join(root,'tsconfig.json'),'utf8'));
const options = ts.convertCompilerOptionsFromJson(cfg.config.compilerOptions,root).options;
const files = context.files.filter(f=>f.endsWith('.ts')).map(f=>path.join(root,f));
const program = ts.createProgram(files,options);
const checker = program.getTypeChecker();
const sf = program.getSourceFile(path.join(root,'src/index.ts'));
const resolve = s => s && (s.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(s) : s);
const target = resolve(checker.getExportsOfModule(checker.getSymbolAtLocation(sf)).find(s=>s.name==='typeFromAST'));
console.log(JSON.stringify({targetDeclarations:target.declarations.map(d=>({file:path.relative(root,d.getSourceFile().fileName),line:d.getSourceFile().getLineAndCharacterOfPosition(d.getStart()).line+1}))}));
const refs=[]; const excluded=[];
for(const file of files){
 const source=program.getSourceFile(file);
 function walk(n){
  if(ts.isIdentifier(n)){
   const symbol=resolve(checker.getSymbolAtLocation(n));
   if(symbol===target){
    const start=source.getLineAndCharacterOfPosition(n.getStart(source));
    const end=source.getLineAndCharacterOfPosition(n.getEnd());
    const row={target:'typeFromAST',file:path.relative(root,file),line:start.line+1,column:start.character,end_line:end.line+1,end_column:end.character};
    if(target.declarations.some(d=>d.name===n)) excluded.push(row);
    else refs.push(row);
   }
  }
  ts.forEachChild(n,walk);
 }
 walk(source);
}
refs.sort((a,b)=>a.file.localeCompare(b.file)||a.line-b.line||a.column-b.column);
const diagnostics=ts.getPreEmitDiagnostics(program);
console.log(JSON.stringify({references:refs,excluded_declarations:excluded,reference_count:refs.length,diagnostic_count:diagnostics.length,diagnostics:diagnostics.slice(0,10).map(d=>ts.flattenDiagnosticMessageText(d.messageText,'\\n'))},null,2));
NODE"
